{
    aggregate_values <- function(df, key_col, val_col) {
        df %>% dplyr::distinct(dplyr::across(dplyr::all_of(c(key_col, 
            val_col)))) %>% dplyr::group_by(dplyr::across(dplyr::all_of(key_col))) %>% 
            dplyr::summarise(`:=`(!!val_col, {
                vals <- unique(.data[[val_col]])
                non_na <- sort(vals[!is.na(vals)])
                if (length(non_na) == 0) {
                  NA_character_
                }
                else if (length(non_na) == 1) {
                  non_na
                }
                else {
                  paste(non_na, collapse = "; ")
                }
            }), .groups = "drop")
    }
    df1 <- aggregate_values(df1, key, param_col)
    df2 <- aggregate_values(df2, key, param_col)
    col1 <- paste0(param_col, "_", name1)
    col2 <- paste0(param_col, "_", name2)
    if (nrow(df1) == 0 || nrow(df2) == 0) {
        empty_keys <- if (nrow(df1) > 0) {
            df1[0, key, drop = FALSE]
        }
        else {
            df2[0, key, drop = FALSE]
        }
        return(dplyr::bind_cols(empty_keys, dplyr::tibble(`:=`(!!col1, 
            character()), `:=`(!!col2, character()), different = logical())))
    }
    result <- df1 %>% dplyr::inner_join(df2, by = key, suffix = c(paste0("_", 
        name1), paste0("_", name2))) %>% dplyr::select(dplyr::all_of(c(key, 
        col1, col2))) %>% dplyr::mutate(different = dplyr::case_when(is.na(.data[[col1]]) & 
        is.na(.data[[col2]]) ~ FALSE, xor(is.na(.data[[col1]]), 
        is.na(.data[[col2]])) ~ TRUE, TRUE ~ .data[[col1]] != 
        .data[[col2]]))
    if (only_diff) {
        result <- dplyr::filter(result, .data$different)
    }
    result
}

{
    if (is.null(dep_string)) {
        return(data.frame(pkg = character(), version = character(), 
            stringsAsFactors = FALSE))
    }
    dep_string <- gsub("\\\\n|\\\\r|[\r\n]", " ", dep_string)
    dep_string <- gsub("\\s+", " ", dep_string)
    parts <- unlist(strsplit(dep_string, ","))
    parts <- trimws(parts)
    result <- lapply(parts, function(entry) {
        pkg <- trimws(gsub("\\s*\\(.*\\)", "", entry))
        m <- regmatches(entry, regexec("\\(([^\\)]+)\\)", entry))[[1]]
        version <- if (length(m) >= 2) 
            m[2]
        else NA
        c(pkg = pkg, version = version)
    })
    df <- do.call(rbind, result)
    colnames(df) <- c("pkg", "version")
    rownames(df) <- df[, "pkg"]
    as.data.frame(df, stringsAsFactors = FALSE)
}

