        if (!requireNamespace(pkg_name, quietly = TRUE)) {
            stop(sprintf("Package '%s' is not installed on current .libPaths().", 
                pkg_name), call. = FALSE)
        }
        found <- as.character(utils::packageVersion(pkg_name))
        want <- as.character(package_version(pkg_version))
        if (!identical(found, want)) {
            stop(sprintf("Found %s %s, but you requested %s. Adjust lib_paths or install that version.", 
                pkg_name, found, want), call. = FALSE)
