            names(prune)) {
            prune_set <- unique(strip_ns(as.character(prune$exported_function)))
        }
        else {
            stop("`prune` must be NULL, a character vector, or a data.frame with column 'exported_function'.", 
                call. = FALSE)
        }
    }
    vn <- igraph::V(g)$name
    vn_stripped <- strip_ns(vn)
    pick_vertex_name <- function(fun) {
        exact <- vn[vn %in% c(fun, paste0(pkg_name, "::", fun))]
        if (length(exact)) {
            return(exact[1])
        }
        idx <- which(vn_stripped == strip_ns(fun))
        if (!length(idx)) {
            return(NA_character_)
        }
        in_pkg <- startsWith(vn[idx], paste0(pkg_name, "::"))
        if (any(in_pkg)) 
            vn[idx[which(in_pkg)][1]]
        else vn[idx[1]]
    }
    max_depth <- if (is.infinite(depth)) 
        igraph::vcount(g)
    else as.integer(depth)
    build_node <- function(node_name, depth_left, seen) {
        node_key <- key_name(node_name)
        if (is.na(node_name) || !nzchar(node_name) || !(node_name %in% 
            vn)) {
            return(NULL)
        }
        if (node_name %in% seen) {
            return(list(`__cycle_to` = node_key))
        }
        if (depth_left <= 0) {
            return(NULL)
        }
        vsel <- which(vn == node_name)
        if (!length(vsel)) {
            return(NULL)
        }
        nbrs <- igraph::neighbors(g, v = igraph::V(g)[vsel], 
            mode = mode)
        if (length(nbrs) == 0) {
            return(NULL)
        }
        child_names <- sort(igraph::V(g)[nbrs]$name)
        out <- vector("list", length(child_names))
        names(out) <- vapply(child_names, key_name, character(1))
        for (i in seq_along(child_names)) {
            child_val <- build_node(child_names[i], depth_left - 
                1, c(seen, node_name))
            if (is.null(child_val)) 
                out[i] <- list(NULL)
            else out[[i]] <- child_val
        }
        out
    }
    first_level_vertex_names <- character()
    if (!is.null(prune_set)) {
        if (!is.null(root)) {
            if (strip_ns(root) %in% prune_set) {
                picked <- pick_vertex_name(root)
                if (!length(picked)) {
                  stop("Specified `root` not found in the package call graph.")
                }
                first_level_vertex_names <- picked
            }
            else {
                stop("`root` is not in the supplied exported function set (`prune`).", 
                  call. = FALSE)
            }
        }
        else {
            mapped <- vapply(prune_set, pick_vertex_name, character(1))
            first_level_vertex_names <- unname(mapped[!is.na(mapped) & 
                nzchar(mapped)])
            if (!length(first_level_vertex_names)) {
                unknown <- setdiff(prune_set, vn_stripped)
                stop(sprintf("None of the exported functions in `prune` were found in the package call graph. Missing: %s", 
                  paste(unknown, collapse = ", ")), call. = FALSE)
            }
        }
    }
    else {
        if (!is.null(root)) {
            picked <- pick_vertex_name(root)
            if (is.na(picked) || !nzchar(picked)) {
                stop(sprintf("Root function '%s' not found in the package call graph for '%s'.", 
                  root, pkg_name), call. = FALSE)
            }
            first_level_vertex_names <- picked
        }
        else {
            if (direction == "downstream") {
                indeg <- igraph::degree(g, mode = "in")
                roots <- names(indeg[indeg == 0])
                if (!length(roots)) 
                  roots <- igraph::V(g)$name
            }
            else {
                outdeg <- igraph::degree(g, mode = "out")
                roots <- names(outdeg[outdeg == 0])
                if (!length(roots)) 
                  roots <- igraph::V(g)$name
            }
            first_level_vertex_names <- sort(roots)
        }
    }
    res <- list()
    res[[pkg_name]] <- list()
    res[[pkg_name]]$version <- as.character(utils::packageVersion(pkg_name))
    for (v in first_level_vertex_names) {
        r_key <- key_name(v)
        res[[pkg_name]][r_key] <- list(build_node(v, max_depth, 
            seen = character()))
    }
    return(res)
}

{
    if (use_isolated_lib) {
        message(paste0("Creating isolated library path for ", 
            package_name, " ", version))
        lib_path <- file.path(tempdir(), paste0(package_name, 
            "_", version))
        dir.create(lib_path, showWarnings = FALSE)
        old_lib <- .libPaths()
        on.exit(.libPaths(old_lib))
        .libPaths(c(lib_path, old_lib))
        old_options <- options()
        on.exit(options(old_options), add = TRUE)
        all_old_env <- Sys.getenv()
        on.exit({
            current_env <- Sys.getenv()
            added_vars <- setdiff(names(current_env), names(all_old_env))
            if (length(added_vars) > 0) {
                try(Sys.unsetenv(added_vars), silent = TRUE)
            }
            do.call(Sys.setenv, as.list(all_old_env))
        }, add = TRUE)
        if (package_name %in% loadedNamespaces()) {
            message(paste0("Unloading cached ", package_name, 
                " from namespace"))
            try(unloadNamespace(package_name), silent = TRUE)
        }
    }
    temp_file <- tryCatch({
        remotes::download_version(package = package_name, version = version)
    }, error = function(e) {
        message(paste("Failed to download version", version, 
            ":", e$message))
        return(NULL)
    })
    if (is.null(temp_file)) {
        return(NULL)
    }
    temp_dir <- tempfile()
    dir.create(temp_dir)
    untar(temp_file, exdir = temp_dir)
    pkg_source_path <- list.dirs(temp_dir, full.names = TRUE, 
        recursive = FALSE)[1]
    pkg_desc <- get_pkg_desc(pkg_source_path)
    func_names <- tryCatch({
        get_package_functions(pkg_source_path)
    }, error = function(e) {
        message(paste("Failed to parse functions:", e$message))
        return(NULL)
    })
    list(desc = pkg_desc, functions = func_names)
}

{
