{
    ch <- list(tee = "|-- ", elbow = "\\-- ", pipe = "|   ", 
        blank = "    ")
    if (is.list(tree) && length(tree) == 1L && is.list(tree[[1]]) && 
        "version" %in% names(tree[[1]])) {
        pkg_name <- names(tree)[1]
        inner <- tree[[1]]
    }
    else if (is.list(tree) && "version" %in% names(tree)) {
        pkg_name <- "package"
        inner <- tree
    }
    else {
        stop("`tree` must be the object returned by function_tree_nested(), or its inner package list.")
    }
    ver <- tryCatch(as.character(inner$version), error = function(e) {
        NA_character_
    })
    header <- if (show_version && !is.na(ver) && nzchar(ver)) {
        paste0(pkg_name, " (v", ver, ")")
    }
    else {
        pkg_name
    }
    cat(ch$elbow, header, "\n", sep = "")
    roots <- inner[setdiff(names(inner), "version")]
    print_children <- function(nodes, pref) {
        if (length(nodes) == 0) {
            return(invisible())
        }
        nms <- names(nodes)
        for (i in seq_along(nms)) {
            nm <- nms[i]
            val <- nodes[[nm]]
            last <- (i == length(nms))
            cat(pref, if (last) 
                ch$elbow
            else ch$tee, nm, sep = "")
            is_cycle <- is.list(val) && !is.null(names(val)) && 
                "__cycle_to" %in% names(val)
            if (is_cycle) {
                cat(" (cycle to ", val$`__cycle_to`, ")", sep = "")
            }
            cat("\n")
            if (!is.null(val) && !is_cycle && is.list(val)) {
                next_pref <- paste0(pref, if (last) 
                  ch$blank
                else ch$pipe)
                print_children(val, next_pref)
            }
        }
        invisible()
    }
    print_children(roots, pref = ch$blank)
    invisible(tree)
}

