        .libPaths(c(lib_path, old_lib))
        old_options <- options()
        on.exit(options(old_options), add = TRUE)
        all_old_env <- Sys.getenv()
        on.exit({
            current_env <- Sys.getenv()
            added_vars <- setdiff(names(current_env), names(all_old_env))
            if (length(added_vars) > 0) {
                try(Sys.unsetenv(added_vars), silent = TRUE)
            }
            do.call(Sys.setenv, as.list(all_old_env))
        }, add = TRUE)
        if (package_name %in% loadedNamespaces()) {
            message(paste0("Unloading cached ", package_name, 
                " from namespace"))
            try(unloadNamespace(package_name), silent = TRUE)
        }
    }
    temp_file <- tryCatch({
        remotes::download_version(package = package_name, version = version)
    }, error = function(e) {
        message(paste("Failed to download version", version, 
            ":", e$message))
        return(NULL)
    })
    if (is.null(temp_file)) {
        return(NULL)
    }
    temp_dir <- tempfile()
    dir.create(temp_dir)
    untar(temp_file, exdir = temp_dir)
    pkg_source_path <- list.dirs(temp_dir, full.names = TRUE, 
        recursive = FALSE)[1]
    pkg_desc <- get_pkg_desc(pkg_source_path)
    func_names <- tryCatch({
        get_package_functions(pkg_source_path)
    }, error = function(e) {
        message(paste("Failed to parse functions:", e$message))
        return(NULL)
    })
    list(desc = pkg_desc, functions = func_names)
}

{
    cat("\n-- Functions --\n")
    if (length(func_cmp$added)) {
        cat("  Added:\n")
        for (fn in names(func_cmp$added)) {
            args <- format_formals(func_cmp$added[[fn]])
            cat(sprintf("    + %s(%s)\n", fn, paste(args, collapse = ", ")))
        }
    }
    if (length(func_cmp$removed)) {
        cat("  Removed:\n")
        for (fn in names(func_cmp$removed)) {
            args <- format_formals(func_cmp$removed[[fn]])
            cat(sprintf("    - %s(%s)\n", fn, paste(args, collapse = ", ")))
        }
    }
    if (length(func_cmp$modified)) {
        cat("  Modified:\n")
        for (fn in names(func_cmp$modified)) {
            old_args <- format_formals(func_cmp$modified[[fn]]$old)
            new_args <- format_formals(func_cmp$modified[[fn]]$new)
            cat(sprintf("    * %s\n", fn))
            cat(sprintf("      - %s: (%s)\n", old_version, paste(old_args, 
                collapse = ", ")))
            cat(sprintf("      + %s: (%s)\n", new_version, paste(new_args, 
                collapse = ", ")))
        }
    }
    invisible(NULL)
}
